<template>
<div class="pro-page tipster-dashboard page-animate"><div class="dashboard-shell">
<aside class="dashboard-nav"><div class="dashboard-brand"><span>BRATIPSTERS</span><b>TIPSTER HUB</b></div><RouterLink to="/tipster-dashboard">Overview</RouterLink><a href="#submit-prediction">Create Prediction</a><a href="#predictions">My Predictions</a><a href="#analytics">Analytics</a><a href="#revenue">Revenue & Earnings</a><a href="#profile">Profile Settings</a><RouterLink to="/subscription">Premium</RouterLink><RouterLink to="/">← Back to site</RouterLink></aside>
<main class="dashboard-content">
<section class="td-hero"><div class="td-hero-main"><div class="td-avatar">{{ initials(profile.username||auth.user?.name||'T') }}</div><div><span class="eyebrow">Professional tipster workspace</span><h1>{{ profile?.username||auth.user?.name||'Tipster' }}</h1><p>Track your record, publish predictions, manage earnings and maintain your public profile from one workspace.</p><div class="td-status"><i></i> Approved tipster <span>•</span> Premium can be active on this same account</div></div></div><div class="td-hero-actions"><RouterLink :to="profile?.username?`/tipsters/${encodeURIComponent(profile.username)}`:'/tipsters'" class="ghost">Public profile</RouterLink><button class="btn" @click="focusSubmit">+ New prediction</button></div></section>
<section class="td-kpis"><div class="td-kpi"><span>Total predictions</span><b>{{ stats.total }}</b><small>all submitted tips</small></div><div class="td-kpi"><span>Won</span><b>{{ stats.won }}</b><small>settled winners</small></div><div class="td-kpi"><span>Lost</span><b>{{ stats.lost }}</b><small>settled losses</small></div><div class="td-kpi"><span>Win rate</span><b>{{ stats.winRate }}%</b><small>{{ stats.settled }} settled</small></div><div class="td-kpi"><span>Current streak</span><b>{{ profile.currentStreak||0 }}</b><small>consecutive wins</small></div></section>
<section id="analytics" class="pro-panel analytics-panel"><div class="pro-section-head"><div><span class="eyebrow">Prediction intelligence</span><h2>Performance analytics</h2><p>Built from your recorded prediction results.</p></div><span class="td-review-badge">LIVE RECORD</span></div><div class="analytics-grid"><div class="analytics-card"><span>Settled record</span><strong>{{ stats.won }}W — {{ stats.lost }}L</strong><div class="result-bar"><i :style="{width:stats.winRate+'%'}"></i></div><small>{{ stats.winRate }}% win rate</small></div><div class="analytics-card"><span>Average odds</span><strong>{{ stats.avgOdds.toFixed(2) }}</strong><small>across {{ stats.total }} predictions</small></div><div class="analytics-card"><span>Premium picks</span><strong>{{ stats.premium }}</strong><small>submitted as Premium candidates</small></div><div class="analytics-card"><span>Pending review</span><strong>{{ stats.pending }}</strong><small>not yet published</small></div></div><div class="analytics-breakdown"><div><h3>Results overview</h3><div class="result-row"><span>Won</span><b>{{ stats.won }}</b><em><i :style="{width:stats.total?stats.won/stats.total*100+'%':'0%'}"></i></em></div><div class="result-row"><span>Lost</span><b>{{ stats.lost }}</b><em><i :style="{width:stats.total?stats.lost/stats.total*100+'%':'0%'}"></i></em></div><div class="result-row"><span>Pending / published</span><b>{{ stats.open }}</b><em><i :style="{width:stats.total?stats.open/stats.total*100+'%':'0%'}"></i></em></div></div><div><h3>Recent form</h3><div class="form-dots"><span v-for="(r,i) in recentForm" :key="i" :class="r">{{ r==='won'?'W':r==='lost'?'L':'—' }}</span><small>Latest settled outcomes</small></div></div></div></section>
<section id="revenue" class="td-wallet pro-panel"><div class="td-wallet-head"><div><span class="eyebrow">Revenue & earnings</span><h2>Performance wallet</h2><p>Subscription-revenue rewards are separate from Premium membership and from any betting wallet.</p></div><RouterLink to="/subscription" class="td-wallet-badge">Premium account →</RouterLink></div><div class="td-wallet-grid"><div><small>Available</small><strong>{{ money(wallet?.wallet?.availableBalance) }}</strong><span>Eligible for withdrawal</span></div><div><small>Pending</small><strong>{{ money(wallet?.wallet?.pendingBalance) }}</strong><span>Under review</span></div><div><small>Lifetime earned</small><strong>{{ money(wallet?.wallet?.lifetimeEarned) }}</strong><span>Total rewards</span></div><div><small>Withdrawn</small><strong>{{ money(wallet?.wallet?.lifetimeWithdrawn) }}</strong><span>Completed payouts</span></div></div><div class="td-wallet-actions"><span>Withdrawals are manually reviewed and approved payouts are processed within 1–3 business days.</span><button class="ghost" @click="focusRevenue">Manage payout details</button></div></section>
<div class="td-grid"><main>
<section id="submit-prediction" class="pro-panel td-submit"><div class="pro-section-head"><div><span class="eyebrow">Publishing desk</span><h2>Create prediction</h2><p>Submit an upcoming fixture for review. Once approved, it becomes your public Tipster Pick.</p></div><span class="td-review-badge">REVIEW REQUIRED</span></div><form v-if="matches.length" @submit.prevent="submitPrediction"><div class="td-fields-three"><div class="field"><label>Upcoming fixture</label><select v-model="form.matchId" required @change="selectMatch"><option value="" disabled>Select match</option><option v-for="m in matches" :key="m._id" :value="m._id">{{ matchLabel(m) }}</option></select></div><div class="field"><label>Prediction</label><input v-model="form.prediction" required placeholder="Over 2.5 Goals"/></div><div class="field"><label>Odds</label><input v-model.number="form.odds" type="number" min="1" step=".01" required/></div></div><div class="td-fields-three"><div class="field"><label>Confidence</label><select v-model.number="form.confidence"><option :value="90">90% — Very high</option><option :value="80">80% — High</option><option :value="70">70% — Good</option><option :value="60">60% — Moderate</option><option :value="50">50% — Balanced</option></select></div><div class="field td-analysis-field"><label>Analysis</label><textarea v-model="form.analysis" maxlength="3000" placeholder="Explain the football reasoning behind the selection…"></textarea></div></div><div class="td-submit-foot"><span>Your prediction stays private until approved by the platform.</span><button class="btn" :disabled="submitting||!form.matchId">{{ submitting?'Submitting…':'Submit for review →' }}</button></div><div v-if="message" :class="messageType">{{ message }}</div></form><EmptyState v-else title="No upcoming fixtures" message="The prediction form will become available when future scheduled matches are loaded."/></section>
<section id="predictions" class="pro-panel td-history"><div class="pro-section-head"><div><span class="eyebrow">Prediction history</span><h2>My predictions</h2></div><span>{{ predictions.length }} records</span></div><div v-if="predictions.length" class="td-table"><div class="td-table-head"><span>Fixture</span><span>Selection</span><span>Odds</span><span>Status</span></div><div v-for="p in predictions.slice(0,15)" :key="p._id" class="td-table-row"><div><b>{{ p.fixture||'Football match' }}</b><small>{{ formatDate(p.createdAt) }}</small></div><span>{{ p.prediction }}</span><strong>{{ Number(p.odds||0).toFixed(2) }}</strong><em :class="'td-status-pill '+p.status">{{ statusLabel(p.status) }}</em></div></div><EmptyState v-else title="No predictions yet" message="Your submitted predictions will appear here."/></section>
</main><aside class="td-sidebar"><section id="profile" class="pro-panel td-profile-card"><span class="eyebrow">Public identity</span><h2>Profile settings</h2><div class="field"><label>Bio</label><textarea v-model="profileForm.bio" maxlength="1000" placeholder="Tell members how you approach football analysis…"></textarea></div><div class="field"><label>Country</label><input v-model="profileForm.country" placeholder="Country"/></div><div class="field"><label>Expertise</label><input v-model="expertiseText" placeholder="Premier League, Over 2.5, BTTS"/></div><div class="field"><label>Profile photo URL</label><input v-model="profileForm.profilePhoto" placeholder="https://…"/></div><button class="btn" :disabled="profileSaving" @click="saveProfile">{{ profileSaving?'Saving…':'Save profile' }}</button><p v-if="profileMessage" class="profile-message">{{ profileMessage }}</p></section><section class="pro-panel td-record"><span class="eyebrow">Account snapshot</span><div class="td-record-score"><div><b>{{ stats.winRate }}%</b><span>settled win rate</span></div><div class="td-ring"><span>{{ stats.settled }}</span><small>settled</small></div></div><div class="td-mini-stats"><div><span>Won</span><b>{{stats.won}}</b></div><div><span>Lost</span><b>{{stats.lost}}</b></div><div><span>Open</span><b>{{stats.open}}</b></div></div></section><section class="td-checklist"><span class="eyebrow">Professional checklist</span><h3>Keep your profile ready</h3><div><i>✓</i> Publish clear, evidence-based analysis.</div><div><i>✓</i> Keep your public record accurate.</div><div><i>✓</i> Review earnings before requesting a withdrawal.</div><div><i>✓</i> Use the same account if you also subscribe to Premium.</div></section></aside></div>
</main></div></div>
</template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {RouterLink} from 'vue-router';import {useAuth} from '../stores/auth';import {api} from '../services/api';import EmptyState from '../components/EmptyState.vue';
const auth=useAuth();const predictions=ref<any[]>([]),matches=ref<any[]>([]),wallet=ref<any>(null),profile=ref<any>({}),message=ref(''),messageType=ref('success'),submitting=ref(false),profileSaving=ref(false),profileMessage=ref('');const expertiseText=ref('');const form=reactive<any>({matchId:'',prediction:'',odds:1.5,confidence:80,analysis:''});const profileForm=reactive<any>({bio:'',country:'',profilePhoto:''});
const stats=computed(()=>{const total=predictions.value.length,won=predictions.value.filter(p=>p.status==='won').length,lost=predictions.value.filter(p=>p.status==='lost').length,settled=won+lost,premium=predictions.value.filter(p=>p.isPremium).length,pending=predictions.value.filter(p=>['pending','under_review'].includes(p.status)).length,open=total-settled;const odds=predictions.value.map(p=>Number(p.odds)).filter(n=>n>0);return{total,won,lost,settled,premium,pending,open,winRate:settled?Math.round(won/settled*100):0,avgOdds:odds.length?odds.reduce((a,b)=>a+b,0)/odds.length:0}});const recentForm=computed(()=>predictions.value.filter(p=>['won','lost'].includes(p.status)).slice(0,10).reverse().map(p=>p.status));
function initials(v:string){return v.split(/\s|_/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'T'}function money(v:any){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v||0))}function formatDate(v:any){return v?new Date(v).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—'}function matchLabel(m:any){return `${m.homeTeamId?.shortName||m.homeTeamId?.name||'Home'} vs ${m.awayTeamId?.shortName||m.awayTeamId?.name||'Away'} · ${m.kickoff?new Date(m.kickoff).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'TBC'}`}function statusLabel(s:string){return s==='under_review'?'Under review':s?.replace('_',' ')||'Unknown'}function focusSubmit(){document.getElementById('submit-prediction')?.scrollIntoView({behavior:'smooth',block:'start'})}function focusRevenue(){document.getElementById('revenue')?.scrollIntoView({behavior:'smooth',block:'start'})}function selectMatch(){}
async function load(){try{const d=await api.get('/me/tipster');profile.value=d.data.profile||{};predictions.value=d.data.predictions||[];profileForm.bio=profile.value.bio||'';profileForm.country=profile.value.country||'';profileForm.profilePhoto=profile.value.profilePhoto||'';expertiseText.value=(profile.value.expertise||[]).join(', ')}catch{}try{wallet.value=(await api.get('/me/tipster/wallet')).data}catch{}try{const m=await api.get('/matches?status=scheduled&limit=100');matches.value=(m.data||[]).filter((x:any)=>new Date(x.kickoff).getTime()>Date.now())}catch{matches.value=[]}}
async function submitPrediction(){submitting.value=true;message.value='';try{const d=await api.post('/me/tipster/predictions',{matchId:form.matchId,prediction:form.prediction,odds:form.odds,confidence:form.confidence,analysis:form.analysis});message.value=d.message||'Prediction submitted for review.';Object.assign(form,{matchId:'',prediction:'',odds:1.5,confidence:80,analysis:''});await load()}catch(e:any){messageType.value='error';message.value=e?.message||'Unable to submit prediction.'}finally{submitting.value=false}}
async function saveProfile(){profileSaving.value=true;profileMessage.value='';try{const d=await api.patch('/me/tipster/profile',{bio:profileForm.bio,country:profileForm.country,profilePhoto:profileForm.profilePhoto,expertise:expertiseText.value.split(',').map(x=>x.trim()).filter(Boolean)});profile.value=d.data;profileMessage.value='Profile updated successfully.'}catch(e:any){profileMessage.value=e?.message||'Unable to update profile.'}finally{profileSaving.value=false}}
onMounted(load);
</script>
